{
  "description": "The creature is a low, quadrupedal animal shown in right-facing profile standing on a small patch of bare ground with sparse grass and leaves. It has a broad, flat, amphibian-like head with large round eyes and a wide, slightly upturned mouth, six feathery external gills projecting from the sides of the head and neck, a stout body with a pale, vertically ridged underbelly and a continuous dorsal covering of large overlapping brown-gray scales that extends from the top of the head over the back and sides and onto a long, broad, flattened tail that tapers to a rounded point behind the body, and four thick, fleshy, splayed limbs ending in broad five-toed clawed feet.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and rounded at the snout, light tan with darker speckling, with large prominent round eyes on the sides, small circular nostrils near the tip of the snout, and a wide mouth with a faint smile-like line",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "eyes",
      "looks_like": "large, round and slightly protruding, with a golden-brown iris, dark pupil, and a pale blue-gray outer ring",
      "where": "on the sides of the head, one clearly visible in profile on the right side and the other partially visible on the far side"
    },
    {
      "part": "gills",
      "looks_like": "six external stalk-like structures, dark at the base with dense reddish-brown feathery frills along the edges",
      "where": "three on each side of the head and neck, projecting outward and slightly backward behind the head"
    },
    {
      "part": "scales",
      "looks_like": "large, rounded, overlapping plate-like scales in mottled brown and gray with darker edges, forming a continuous armor",
      "where": "covering the top of the head, the entire back, sides, and dorsal and lateral surfaces of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout, fleshy limbs with wrinkled pale tan skin and muscular joints, splayed outward",
      "where": "two forelimbs under the chest and two hindlimbs under the rear body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, five-toed feet with short dark claws on each toe and wrinkled skin",
      "where": "at the ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, broad at the base and tapering to a rounded point, flattened, completely covered in overlapping scales with transverse scale rows visible underneath",
      "where": "extending behind the body to the left of the image"
    },
    {
      "part": "markings / underbelly",
      "looks_like": "pale cream to light greenish ventral surface with faint vertical rib-like ridges and subtle mottling, contrasting with the darker scaled dorsum",
      "where": "on the underside of the body between the front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
